fn rangeOrder(cp: u21, r: CpRange) std.math.Order {
    if (cp < r.lo) return .lt;
    if (cp > r.hi) return .gt;
    return .eq;
}

/// True when `cp` falls inside one of the sorted, non-overlapping `ranges`.
pub fn inRanges(cp: u21, ranges: []const CpRange) bool {
    return std.sort.binarySearch(CpRange, ranges, cp, rangeOrder) != null;
}

pub fn isWord(cp: u21) bool {
    return inRanges(cp, &word_ranges);
}
pub fn isDigit(cp: u21) bool {
    return inRanges(cp, &digit_ranges);
}
pub fn isSpace(cp: u21) bool {
    return inRanges(cp, &space_ranges);
}

