fn foldEntryOrder(cp: u21, e: FoldEntry) std.math.Order {
    return std.math.order(cp, e.cp);
}

/// Map `cp` to its simple case-folded counterpart (itself when unchanged).
pub fn simpleCaseFold(cp: u21) u21 {
    if (cp < 128) return std.ascii.toLower(@intCast(cp));
    if (std.sort.binarySearch(FoldEntry, &fold_map, cp, foldEntryOrder)) |i| {
        return fold_map[i].to;
    }
    return cp;
}

fn foldGroupOrder(folded: u21, g: FoldGroup) std.math.Order {
    return std.math.order(folded, g.folded);
}

/// Return the static simple-case-fold equivalence class of `cp` (every codepoint
/// that compares equal under folding, including `cp`), or null when `cp` folds
/// only to itself. The returned slice points at compile-time data.
pub fn caselessEquivalents(cp: u21) ?[]const u21 {
    const folded = simpleCaseFold(cp);
    if (std.sort.binarySearch(FoldGroup, &fold_groups, folded, foldGroupOrder)) |i| {
        return fold_groups[i].sources;
    }
    return null;
}

test "unicode case folding" {
    const t = std.testing;
    try t.expectEqual(@as(u21, 'a'), simpleCaseFold('A'));
    try t.expectEqual(@as(u21, 'a'), simpleCaseFold('a'));
    try t.expectEqual(@as(u21, 0x00E9), simpleCaseFold(0x00C9)); // É -> é
    try t.expectEqual(@as(u21, 0x03C3), simpleCaseFold(0x03A3)); // Σ -> σ
    try t.expectEqual(@as(u21, 0x03C3), simpleCaseFold(0x03C2)); // ς -> σ
    try t.expectEqual(@as(u21, 0x00DF), simpleCaseFold(0x1E9E)); // ẞ -> ß
    try t.expectEqual(@as(u21, 0x10428), simpleCaseFold(0x10400)); // Deseret

    const eq = caselessEquivalents('A').?;
    try t.expectEqual(@as(usize, 2), eq.len);
    try t.expectEqual(@as(u21, 'A'), eq[0]);
    try t.expectEqual(@as(u21, 'a'), eq[1]);

    // Final sigma shares an equivalence class with Σ and σ.
    const sigma = caselessEquivalents(0x03C2).?;
    try t.expectEqual(@as(usize, 3), sigma.len);

    // A codepoint with no case pairing folds only to itself.
    try t.expect(caselessEquivalents(0x3042) == null); // あ
}

test "unicode character properties" {
    const t = std.testing;
    try t.expect(isWord('a'));
    try t.expect(isWord('_'));
    try t.expect(isWord(0x3042)); // hiragana あ
    try t.expect(!isWord(' '));
    try t.expect(!isWord('-'));

    try t.expect(isDigit('0'));
    try t.expect(isDigit(0x0660)); // arabic-indic digit zero
    try t.expect(!isDigit('a'));

    try t.expect(isSpace(' '));
    try t.expect(isSpace(0x00A0)); // no-break space
    try t.expect(isSpace(0x3000)); // ideographic space
    try t.expect(!isSpace('a'));

    try t.expect(inRanges(0x3042, &word_ranges));
    try t.expect(!inRanges(0x20000, &digit_ranges));
}

test "unicode property lookup" {
    const t = std.testing;
    try t.expect(lookupProperty("Lu") != null);
    try t.expect(lookupProperty("L") != null);
    try t.expect(lookupProperty("Nd") != null);
    try t.expect(lookupProperty("White_Space") != null);
    try t.expect(lookupProperty("NotAProperty") == null);

    const lu = propertyRanges(lookupProperty("Lu").?);
    try t.expect(inRanges('A', lu));
    try t.expect(!inRanges('a', lu));
}
